namespace sv_ed401d2d32854ed08e33938f7798cd39.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications;

    public NotificationService()
    {
        _notifications = new List<Notification>
        {
            new() { Id = _nextId++, Message = "Welcome to the application!", Timestamp = DateTime.Now.AddMinutes(-30) },
            new() { Id = _nextId++, Message = "Your profile was updated successfully.", Timestamp = DateTime.Now.AddMinutes(-15) },
            new() { Id = _nextId++, Message = "New feature: Dark mode is now available.", Timestamp = DateTime.Now.AddMinutes(-5) }
        };
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        return Task.FromResult(_notifications.ToList());
    }

    public Task<List<Notification>> GetNewNotificationsSinceAsync(int lastId)
    {
        // Simulate occasional new notifications
        if (Random.Shared.Next(3) == 0)
        {
            _notifications.Add(new Notification
            {
                Id = _nextId++,
                Message = $"New event at {DateTime.Now:HH:mm:ss}",
                Timestamp = DateTime.Now
            });
        }

        var newer = _notifications.Where(n => n.Id > lastId).ToList();
        return Task.FromResult(newer);
    }
}

